package com.tihai.utils;
import org.springframework.stereotype.Service;import com.fasterxml.jackson.databind.ObjectMapper;import java.util.*;import java.nio.file.*;import java.net.*;import java.io.*;
@Service public class RainStore {
 private final Path root;private final ObjectMapper json=new ObjectMapper();private Map<String,Map<String,Object>> tasks=new LinkedHashMap<>();
 public RainStore(){this(com.tihai.utils.InstallRoot.path(""));}public RainStore(Path root){this.root=root;try{Path f=root.resolve("data/yuketang/tasks.json");if(Files.exists(f))tasks=json.readValue(Files.readAllBytes(f),Map.class);for(Map t:tasks.values())if(Arrays.asList("running","starting","verification","ready").contains(t.get("state"))){t.put("state","stopped");t.put("message","上次运行已中断，请核对平台后继续；不会自动提交");}}catch(Exception e){throw new IllegalStateException("雨课堂记录读取失败，保留原文件",e);}}
 public static String validate(String input,boolean lesson)throws IOException{try{URI u=new URI(input==null?"":input.trim());String h=u.getHost();if(!"https".equals(u.getScheme())||h==null||u.getUserInfo()!=null||u.getPort()!=-1||!(h.equals("yuketang.cn")||h.endsWith(".yuketang.cn")||h.equals("gdufemooc.cn")||h.endsWith(".gdufemooc.cn")))throw new Exception();if(lesson&&!(u.getPath().startsWith("/v2/web/")||u.getPath().startsWith("/pro/lms/")||u.getPath().startsWith("/ai-workspace/lms-graph/")))throw new IOException("请选择课程目录、课件或练习地址");return u.toString();}catch(IOException e){throw e;}catch(Exception e){throw new IOException("请输入雨课堂学校入口的HTTPS地址（yuketang.cn或gdufemooc.cn）");}}
 private synchronized void save()throws IOException{Path f=root.resolve("data/yuketang/tasks.json");Files.createDirectories(f.getParent());Path tmp=f.resolveSibling("tasks.json.new");Files.write(tmp,json.writeValueAsBytes(tasks));try{Files.move(tmp,f,StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}catch(AtomicMoveNotSupportedException e){Files.move(tmp,f,StandardCopyOption.REPLACE_EXISTING);}}
 private Map<String,Object> copy(Map m){return json.convertValue(m,Map.class);}
 public synchronized Map<String,Object> add(String account,String title,String url,String module)throws IOException{validate(url,true);if(title==null||title.trim().isEmpty()||title.length()>200)throw new IOException("请输入课程或任务名称");if(!Arrays.asList("chapters","homework","exams").contains(module))throw new IOException("任务分类无效");for(Map t:tasks.values())if(account.equals(t.get("accountId"))&&url.equals(t.get("url"))&&module.equals(t.get("module")))return copy(t);Map t=new LinkedHashMap();String id=UUID.randomUUID().toString();t.put("id",id);t.put("accountId",account);t.put("title",title.trim());t.put("url",url);t.put("module",module);t.put("state","stopped");t.put("message","已添加，等待开始；雨课堂适配待真实账号验证");t.put("autoAI",false);t.put("autoSubmit",false);tasks.put(id,t);save();return copy(t);}
 public synchronized List<Map<String,Object>> list(String account,String module){List<Map<String,Object>> out=new ArrayList<>();for(Map t:tasks.values())if(account.equals(t.get("accountId"))&&(module==null||module.equals(t.get("module"))))out.add(copy(t));return out;}
 public synchronized Map<String,Object> task(String id,String account)throws IOException{Map t=tasks.get(id);if(t==null||!account.equals(t.get("accountId")))throw new IOException("任务不属于当前雨课堂账号");return copy(t);}
 public synchronized void update(String id,String account,Map<String,Object> values)throws IOException{task(id,account);for(String k:Arrays.asList("state","message","position","duration","chapter","questionIndex","questionTotal","autoAI","autoSubmit","progress","updatedAt"))if(values.containsKey(k))tasks.get(id).put(k,values.get(k));tasks.get(id).put("updatedAt",java.time.LocalDateTime.now().toString());save();}
 public synchronized void delete(String id,String account)throws IOException{Map t=task(id,account);if(Arrays.asList("running","starting","verification","ready").contains(t.get("state")))throw new IOException("请先停止任务再删除");tasks.remove(id);save();}
}
